  var message = get("@css:#qd-error@text");
  if (message) throw new Error(message);
  if (get("@css:main.content.lock-mask@html")) fail("起点显示本章需订阅，请确认登录了购买本章的账号。");
  var decoded = get("@css:#qd-decoded p@text");
  if (decoded) {
    var version = get("@css:#qd-decoded@data-version");
    var jobs = Number(get("@css:#qd-decoded@data-jobs"));
    var changed = Number(get("@css:#qd-decoded@data-changed"));
    if (version !== "8.2" || !(jobs > 0) || !(changed > 0)) fail("字形处理结果缺少有效完成标记，请刷新正文。");
    java.log("[QD8.2] mode=decoded jobs=" + jobs + " changed=" + changed);
    return decoded;
  }
  var info;
  try {
    // Legado @html returns outer HTML and removes script/style nodes.
    // Read the Jsoup script data directly; text() also omits script data.
    var metaElements = java.getElement("@css:script#vite-plugin-ssr_pageContext");
    var metaNode = metaElements && metaElements.first();
    var rawMeta = metaNode ? String(metaNode.data()) : "";
    info = JSON.parse(rawMeta).pageContext.pageProps.pageData.chapterInfo;
  }
  catch (e) { fail("章节元数据缺失或读取失败，请反馈本章正文调试记录。"); }
  if (!info) fail("章节元数据尚未加载，请刷新正文。");
  if (get("@css:main.r-font-encrypt@html") || Number(info.fEnS)>0 || info.randomFont || info.fixedFontTtf || info.fixedFontWoff2) {
    fail("检测到动态字体，但未收到字形处理结果；已停止保存正文。请反馈本章正文调试记录。");
  }
  if (get("@css:#qd-status@data-version") !== "8.2" || get("@css:#qd-status@data-mode") !== "plain") {
    fail("网页未经过 V8.2 处理，请确认已覆盖导入并刷新正文。");
  }
  var plain = get("@css:main.content .content-text@text");
  if (!plain) fail("正文尚未加载，请完成书源登录中的网页验证后重试。");
  java.log("[QD8.2] mode=plain");
  return plain;
})()

